"""Build offline HTML slides around real ViewerControl captures and HyperFrames clips."""
from pathlib import Path
import json

ROOT = Path(__file__).resolve().parents[1]
OUT = ROOT / 'artifacts' / 'presentation' / 'output'
SLIDES = [
 dict(title='DICOM RT\nfor QuickLook', text=['Images, structures and treatment plans. One press of the space bar.','Feature tour · Version 0.2.0'], image='image-clean.png', caption='Benchmark M01 · actual views rendered by the Windows viewer', cover=True),
 dict(title='Open a file.\nStart exploring.', text=['Select a DICOM file in Explorer and press Space. The selected image appears before directory indexing finishes.','A progress indicator tracks the search. RT objects are prioritised; the remaining image catalogue follows.'], image='rt-overview.png', caption='RT controls on the left · DICOM tags on the right · the image stays central'),
 dict(title='Built to\nrespond quickly', text=['Image first. RT next. A short header pass finds plans, structures and dose without relying on filenames.','Measured on 194 benchmark files: selected CT decoded in 31 ms, first plan ready in 1.45 s, directory indexed in 2.20 s.'], image='image-clean.png', caption='Fresh viewer, warm OS cache. Component milestones exclude QuickLook startup and screen presentation; not a cold-start guarantee. Bounded cache and cancellable rendering.'),
 dict(title='Scroll through\nthe series', text=['The wheel and slice slider navigate the matching image stack.','The previous complete frame remains visible until the new image and its labels are ready together.'], video='01-scroll.mp4', poster='image-clean.png', caption='Actual rendered CT slices · HyperFrames sequence, not a screen-recorded latency benchmark'),
 dict(title='Choose your\nplane', text=['Native, axial, coronal, sagittal or three linked views.','Click to position the crosshair. Right-drag changes window and level; zoom and Fit control the field of view.'], image='mpr-three.png', caption='MPR becomes available when a geometrically supported volume has loaded'),
 dict(title='Find the\nstructure', text=['Search targets and organs at risk. Checkboxes control visibility.','Click a structure name to jump to its contour. All and None change the selection together.'], image='structures-jump.png', caption='Original contours and actual plane-intersection segments in the image views'),
 dict(title='Dose, with\nclear controls', text=['Hide dose completely, or choose colorwash, isodose lines, or both.','Adjust opacity, the lower and upper wash thresholds, and your own isodose levels.'], video='04-dose.mp4', poster='dose-combined.png', caption='Percent levels refer to each dose object’s maximum; stored units remain explicit'),
 dict(title='One timeline.\nEvery beam.', text=['Expand MLC into the centre. Select a beam or scrub across the whole plan.','Dots mark beam ends. Playback crosses beam boundaries; a separate CP/s control sets the animation speed.'], video='02-mlc.mp4', poster='mlc.png', caption='MLC coordinates at isocentre · control-point animation, not actual delivery timing'),
 dict(title='DVH, on\ndemand', text=['Open the DVH view to calculate curves. Choose a dose and compare structures using the legend.','Volume, sampling resolution and dose coverage stay visible. Partial coverage uses a dashed curve.'], image='dvh.png', caption='All 55 benchmark structures calculated · approximate contour-grid DVH, not TPS-equivalent'),
 dict(title='See the plan\nin 3D', text=['Drag to orbit. Use the wheel to zoom.','Toggle bone, skin, targets/OARs and dose separately. Opacity and isodose settings reveal structures inside.'], video='03-3d.mp4', poster='three-d-roi.png', caption='All 55 benchmark ROIs supported; this orbit selects five for clarity. Bounded surface approximations.'),
 dict(title='Registered\nimage fusion', text=['The overlapping-squares icon opens the overlay picker.','Select the base image separately, then a registered overlay and blend fraction. An unambiguous spatial REG aligns supported images and RT data.'], image='fusion.png', choices=[['Fused image','fusion.png'],['Overlay picker','fusion-picker.png']], caption='Synthetic CT/MR example · benchmark M01 has no MR or REG. Picker detail is a separate actual UI capture.', synthetic=True),
 dict(title='One plan.\nOr a plan sum.', text=['The left-hand dropdown switches between plans and a voxelwise sum.','Eligible physical Gy PLAN doses are aligned in space. Included doses, exclusions and common coverage are reported.'], image='plan-sum.png', caption='Synthetic two-plan example · no fraction scaling; dose outside common coverage stays unknown', synthetic=True),
 dict(title='Full DICOM\ntag search', text=['Search tag numbers, names, values and nested paths across the complete metadata tree. This plan exposes 79,040 attributes.','Expand sequences and items yourself. During search, matching ancestors open automatically; clearing it restores your manual tree state.'], image='tags-collapsed.png', choices=[['Collapsed tree','tags-collapsed.png'],['Expanded sequence','tags-expanded.png'],['Full search','tags-search.png']], caption='All nested metadata included. Binary payloads are excluded; long displayed/searchable values are capped at 8,192 characters. Demo identifiers redacted.'),
 dict(title='Local.\nRead only.', text=['The viewer reads the immediate folder. Source DICOM files remain unchanged; no persistent patient cache is created.','DVH, dose sums, 3D and MLC support inspection. Unsupported geometry and missing relationships are reported explicitly.'], image='three-d-dose.png', caption='Current limits: no deformable REG, Enhanced-MPR, compressed or colour image pixels. Research and inspection; no clinical approval.'),
]

HTML = r'''<!doctype html>
<html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>DICOM RT · Feature Tour</title>
<style>
:root{color-scheme:dark;--bg:#101314;--ink:#eef4f5;--muted:#a5b4ba;--accent:#65d8ce}*{box-sizing:border-box}body{margin:0;background:var(--bg);color:var(--ink);font:18px/1.5 'Segoe UI Variable','Segoe UI',Arial,sans-serif;overflow:hidden}button,select{font:inherit}button{color:var(--muted);border:0;background:transparent;cursor:pointer;padding:8px 13px;border-radius:5px}button:hover,button:focus-visible{background:#253031;color:var(--ink);outline:1px solid var(--accent)}button:disabled{opacity:.25;cursor:default}header{height:80px;padding:22px 4vw;display:flex;align-items:center;gap:12px}header img{width:32px;height:32px}header span{font-size:15px;letter-spacing:.08em;color:var(--muted)}header .version{margin-left:auto;font-size:12px;letter-spacing:.04em}main{height:calc(100vh - 148px);padding:22px 4vw 14px;display:grid;grid-template-columns:minmax(250px,.72fr) minmax(0,1.85fr);gap:3vw;align-items:center}.copy{align-self:center;padding-bottom:20px}h1{font-size:clamp(36px,3.5vw,62px);line-height:1.06;letter-spacing:-.045em;margin:0 0 28px;font-weight:600;white-space:pre-line}.copy p{color:var(--muted);font-size:clamp(17px,1.38vw,23px);line-height:1.55;margin:0 0 20px;max-width:35ch}.copy .synthetic{color:var(--accent);font-size:14px;letter-spacing:.03em;margin-bottom:22px}.visual{min-width:0;align-self:center}figure{margin:0}figure img,figure video{display:block;width:100%;max-height:calc(100vh - 255px);object-fit:contain;background:#0b0e10}figure img{cursor:zoom-in}.visual:has(.choices) figure img{max-height:calc(100vh - 335px)}figcaption{font-size:clamp(12px,.98vw,16px);line-height:1.45;color:var(--muted);margin-top:16px;min-height:3em;max-width:94ch}.choices{display:flex;gap:5px;margin-top:9px}.choices button{font-size:14px;border-bottom:2px solid transparent;border-radius:0}.choices button.active{color:var(--accent);border-bottom-color:var(--accent)}footer{height:68px;margin:0 4vw;display:flex;align-items:center;gap:10px;border-top:1px solid #293235;color:var(--muted);font-size:13px}footer .guide{margin-right:auto}#position{min-width:58px;text-align:center;letter-spacing:.08em}.bar{position:fixed;bottom:0;left:0;height:3px;background:var(--accent);transition:width .2s}.menu{position:fixed;inset:80px 4vw 80px;z-index:10;background:#151b1d;overflow:auto;padding:25px 35px;border:1px solid #3b4b50}.menu[hidden]{display:none}.menu h2{font-size:28px;font-weight:500}.menu ol{columns:2;column-gap:50px;list-style:none;padding:0;counter-reset:s}.menu li{break-inside:avoid;margin:6px 0}.menu button{text-align:left;width:100%;font-size:20px;padding:12px}.menu button:before{counter-increment:s;content:counter(s,decimal-leading-zero);font-size:13px;margin-right:20px;color:var(--accent)}dialog{border:0;padding:0;background:#0b0e10;max-width:98vw;max-height:96vh}dialog::backdrop{background:#000d}dialog img{display:block;max-width:96vw;max-height:92vh;object-fit:contain}dialog button{position:absolute;right:8px;top:8px;background:#101314e8;color:white}.cover h1{font-size:clamp(44px,4.5vw,76px)}.cover .copy p:first-of-type{color:#d1dddf}.fade{animation:appear .22s ease-out}@keyframes appear{from{opacity:.5;transform:translateY(5px)}to{opacity:1;transform:translateY(0)}}@media(max-width:900px){header{height:65px}main{height:calc(100vh - 125px);grid-template-columns:1fr;gap:8px;align-content:start;overflow:auto;padding-top:6px}.copy{padding:0;display:grid;grid-template-columns:.8fr 1.2fr;gap:18px}h1{font-size:30px;margin-bottom:10px}.copy p{font-size:15px;margin-bottom:8px}.copy p:last-of-type{display:none}.copy .synthetic{grid-column:1/-1;margin:0}.visual img,.visual video{max-height:57vh}.visual figcaption{font-size:12px;min-height:0}footer{height:60px}.guide{display:none}.menu ol{columns:1}}@media(prefers-reduced-motion:reduce){.fade{animation:none}.bar{transition:none}}@media print{body{overflow:auto}header,footer,.bar,.menu{display:none}main{height:auto;display:block}figure img{max-height:none}dialog{display:none}}
</style></head><body>
<header><img src="media/logo.png" alt="DICOM RT logo"><span>DICOM RT</span><span class="version">QUICKLOOK · VERSION 0.2</span></header>
<main id="slide" aria-live="polite"></main>
<footer><span class="guide">← → Slides · F Fullscreen · Click an image to enlarge</span><button id="toc" aria-label="Contents">Contents</button><button id="prev" aria-label="Previous slide">←</button><span id="position"></span><button id="next" aria-label="Next slide">→</button><button id="full" aria-label="Fullscreen">⛶</button></footer>
<div class="bar" id="progress"></div><section class="menu" id="menu" hidden><h2>All features</h2><ol id="contents"></ol></section>
<dialog id="zoom"><button aria-label="Close image">✕</button><img alt="Enlarged viewer image"></dialog>
<script>
const slides=__SLIDES__;let index=Math.max(0,Math.min(slides.length-1,Number(location.hash.slice(1)||1)-1));const host=document.querySelector('#slide'),zoom=document.querySelector('#zoom');
const esc=s=>s.replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function show(n){const old=host.querySelector('video');if(old)old.pause();index=Math.max(0,Math.min(slides.length-1,n));const s=slides[index];host.className=(s.cover?'cover ':'')+'fade';const media=s.video?`<video controls autoplay loop muted playsinline preload="metadata" poster="screens/${s.poster}" aria-label="${esc(s.title.replaceAll('\n',' '))}"><source src="media/${s.video}" type="video/mp4"></video>`:`<img src="screens/${s.image}" alt="${esc(s.title.replaceAll('\n',' '))}" loading="eager">`;host.innerHTML=`<div class="copy">${s.synthetic?'<div class="synthetic">SYNTHETIC DEMONSTRATION</div>':''}<h1>${esc(s.title)}</h1>${s.text.map(t=>`<p>${esc(t)}</p>`).join('')}</div><div class="visual"><figure>${media}<figcaption>${esc(s.caption)}</figcaption></figure>${s.choices?'<div class="choices">'+s.choices.map((c,i)=>`<button class="${i===0?'active':''}" data-src="${c[1]}">${c[0]}</button>`).join('')+'</div>':''}</div>`;host.querySelector('img')?.addEventListener('click',e=>{zoom.querySelector('img').src=e.target.src;zoom.showModal()});host.querySelectorAll('.choices button').forEach(b=>b.addEventListener('click',()=>{host.querySelector('figure img').src='screens/'+b.dataset.src;host.querySelectorAll('.choices button').forEach(a=>a.classList.toggle('active',a===b))}));host.querySelector('video')?.play().catch(()=>{});document.querySelector('#position').textContent=String(index+1).padStart(2,'0')+' / '+slides.length;document.querySelector('#prev').disabled=index===0;document.querySelector('#next').disabled=index===slides.length-1;document.querySelector('#progress').style.width=((index+1)/slides.length*100)+'%';history.replaceState(null,'','#'+(index+1));document.title=s.title.replaceAll('\n',' ')+' · DICOM RT';document.querySelector('#menu').hidden=true;}
function fullscreen(){if(document.fullscreenElement)document.exitFullscreen();else document.documentElement.requestFullscreen().catch(()=>{})}document.querySelector('#prev').onclick=()=>show(index-1);document.querySelector('#next').onclick=()=>show(index+1);document.querySelector('#full').onclick=fullscreen;document.querySelector('#toc').onclick=()=>{const m=document.querySelector('#menu');m.hidden=!m.hidden};document.querySelector('#contents').innerHTML=slides.map((s,i)=>`<li><button data-index="${i}">${esc(s.title.replaceAll('\n',' '))}</button></li>`).join('');document.querySelectorAll('#contents button').forEach(b=>b.onclick=()=>show(+b.dataset.index));zoom.querySelector('button').onclick=()=>zoom.close();zoom.addEventListener('click',e=>{if(e.target===zoom)zoom.close()});document.addEventListener('keydown',e=>{if(zoom.open)return;if(e.key==='ArrowRight'||e.key==='PageDown'||(e.key===' '&&e.target===document.body)){e.preventDefault();show(index+1)}if(e.key==='ArrowLeft'||e.key==='PageUp'){e.preventDefault();show(index-1)}if(e.key.toLowerCase()==='f')fullscreen();if(e.key==='Escape')document.querySelector('#menu').hidden=true;if(e.key==='Home')show(0);if(e.key==='End')show(slides.length-1)});show(index);
</script></body></html>'''

OUT.mkdir(parents=True,exist_ok=True)
(OUT/'index.html').write_text(HTML.replace('__SLIDES__',json.dumps(SLIDES,ensure_ascii=False)),encoding='utf-8')
(OUT/'START.txt').write_text("""DICOM RT — Feature Tour

Open index.html in a modern browser. Keep the screens and media folders together. The presentation works offline, without external fonts or network requests.

Arrow keys: slides. F: fullscreen. Click images to enlarge. Four MP4 clips can also be played separately.

Views were rendered by the actual WPF component. HyperFrames compositions animate actual rendered states; these are demonstrations, not screen-recorded responsiveness measurements. The main case is the user-authorised nonpatient benchmark M01. Registered CT/MR fusion and the two-plan sum use clearly labelled synthetic fixtures.
""",encoding='utf-8')
print('HTML slides written:',len(SLIDES))
